window.AUTH=window.AUTH||{};window.AUTH["23-997"]={"d":"23-997","id":"2024/23-997","n":"Stanley v. City of Sanford, Florida","briefs":[{"k":"petitioner","label":"Brief of petitioner Karyn D. Stanley","date":"2024-09-16","url":"https://www.supremecourt.gov/DocketPDF/23/23-997/326112/20240916194411347_Stanley%20Opening%20Final.pdf","side":"pet","n":42},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2024-09-23","url":"https://www.supremecourt.gov/DocketPDF/23/23-997/326684/20240923182253908_23-997tsUnitedStates.pdf","side":"us","n":55},{"k":"respondent","label":"Brief of respondent City of Sanford, Florida","date":"2024-11-12","url":"https://www.supremecourt.gov/DocketPDF/23/23-997/331645/20241112164038324_23-997%20Brief%20of%20Respondent.pdf","side":"res","n":65},{"k":"reply","label":"Reply of petitioner Karyn D. Stanley","date":"2024-12-19","url":"https://www.supremecourt.gov/DocketPDF/23/23-997/335650/20241219174736814_No.%2023-997%20Reply%20brief%20of%20petitioner%20.pdf","side":"pet","n":42}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/606us1r53_5i36.pdf","tr":true,"items":[{"t":"case","label":"Arellano v. McDonough","cite":"598 U.S. 1","y":2023,"id":"2022/21-432","sc":1,"sum":"The effective date of an award of service-related disability compensation to a veteran of the United States military determined pursuant to 38 U. S. C. §§5110(a)(1) and 5110(b)(1) is not subject to equitable tolling.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"29"}},{"t":"case","label":"Arizona Governing Committee for Tax Deferred Annuity & Deferred Compensation Plans v. Norris","cite":"463 U.S. 1073","y":1983,"id":"1982/82-52","sc":1,"op":1,"sum":"The State's retirement plan discriminates on the basis of sex in violation of Title VII, and all retirement benefits derived from contributions made after this decision must be calculated without regard to the beneficiary's sex. But benefits derived from contributions made prior to this decision may be calculated as provided by the existing terms of the Arizona plan. 671 F. 2d 330, affirmed in part, reversed in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"6","3":"6"}},{"t":"case","label":"Bank of America Corp. v. City of Miami","cite":"581 U.S. 189","y":2017,"id":"2016/15-1111","sc":1,"sum":"The Court determined that the “aggrieved persons” language of the Fair Housing Act (FHA) does not impose a more narrow standing standard than Article III does and allows a city to sue, but the proximate cause standard requires the plaintiffs to show more than the possibility that a defendant could have foreseen the harm.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Barnhart v. Thomas","cite":"540 U.S. 20","y":2003,"id":"2003/02-763","sc":1,"sum":"The Court held that the SSA's decision had been a reasonable interpretation of the statute and was therefore entitled to deference under Chevron U.S.A. Inc. v. Natural Resources Defense Council, Inc., 467 U.S. 837.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Bethel v. Jefferson","cite":"589 F.2d 631","y":1978,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/589/631/","sum":"Reasoning that a plaintiff who wasn’t in a “unit” of government “in the competitive service” necessarily fell under a Title VII provision governing everyone else.","sumSrc":"brief:0","by":{"0":"42"}},{"t":"case","label":"Biden v. Nebraska","cite":"143 S. Ct. 2355","y":2023,"id":"2022/22-506","sc":1,"sum":"The Secretary of Education does not have authority under the Higher Education Relief Opportunities for Students Act of 2003 (HEROES Act) to establish a student loan forgiveness program that will cancel roughly $430 billion in debt principal and affect nearly all borrowers.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"40"}},{"t":"case","label":"Boesche v. Udall","cite":"373 U.S. 472","y":1963,"id":"1962/332","sc":1,"sum":"The Secretary of the Interior has authority to cancel in an administrative proceeding a noncompetitive lease of public lands issued under the provisions of the Mineral Leasing Act of 1920 in circumstances where such lease was granted in violation of the Act and the regulations promulgated thereunder-i. e., he has power to correct administrative errors of the sort involved in this case by cancellation of leases in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39"}},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2014,"id":"2013/12-158","sc":1,"sum":"The Court found that international treaties cannot overstep state sovereignty, and enforcement should be limited to international affairs.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Castellano v. City of New York","cite":"142 F.3d 58","y":1998,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/142/58/","op":1,"by":{"0":"26","2":"4, 27, 34, 37"}},{"t":"case","label":"City of Chicago v. Fulton","cite":"592 U.S. 154","y":2021,"id":"2020/19-357","sc":1,"sum":"The mere retention of estate property after the filing of a bankruptcy petition does not violate 11 U. S. C. §362(a)(3), which operates as a “stay” of “any act” to “exercise control” over the property of the estate.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"33"}},{"t":"case","label":"-v- City of Los Angeles, Department of Water & Power v. Manhart","cite":"435 U.S. 702","y":1978,"id":"1977/76-1810","sc":1,"sum":"The Court held that the company’s policy was based on aggregate numbers that are not necessarily true for individuals, which violates the Civil Rights Act prohibition of individual discrimination based purely on gender.","sumSrc":"Oyez","by":{"0":"9, 19"}},{"t":"case","label":"Costello v. INS","cite":"376 U.S. 120","y":1964,"id":"1963/83","sc":1,"sum":"Petitioner, while a naturalized citizen, was convicted of two separate offenses involving moral turpitude. Following his subsequent denaturalization on the ground that his citizenship had been acquired by willful misrepresentation, proceedings were brought against him under § 241 (a) (4) of the Immigration and Nationality Act of 1952, which provides for deportation of an alien who at any time after entry \"is …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"sum":"The Court held that an federal habeas corpus petition is not an \"application for State post-conviction or other collateral review\" within the meaning of 28 USC section 2244(d)(2). \"Section 2244(d)(2) therefore did not toll the limitation period during the pendency of [Walker's] first federal habeas petition,\" wrote Justice O'Connor. \"[I]f the statute were construed so as to give applications for federal review the same tolling effect as applications for state collateral review, then [section] 2244(d)(2) would furnish little incentive for individuals to seek relief from the state courts before filing federal habeas petitions,\" concluded Justice O'Connor.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Florida v. Long","cite":"487 U.S. 223","y":1988,"id":"1987/86-1685","sc":1,"sum":"Los Angeles Dept. of Water and Power v. Manhart, 435 U. S. 702, held that unequal pension plan contributions for male and female employees based on actuarial tables reflecting women's greater life spans violated the sex discrimination prohibitions of Title VII of the Civil Rights Act of 1964. Arizona Governing Committee for Tax Deferred Annuity and Deferred Compensation Plans v. Norris, 463 U. S. 1073, extended this …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 19"}},{"t":"case","label":"Gardner v. Collins","cite":"27 U.S. 58","y":1829,"id":"scdb/1829-004","sc":1,"sum":"Where the question upon the construction of the statute o'f a State relative to real property, has been settled by any judicial decisio.n in the state' where the lane lies; this Court, upon the uniform principles adopted by it, would recognise that decision as a part of (he local law. [85]","sumSrc":"Headnote (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"Graham County Soil & Water Conservation District v. United States ex rel. Wilson","cite":"545 U.S. 409","y":2005,"id":"2004/04-169","sc":1,"sum":"The Court ruled that the six-year statute of limitations did not apply to suits for retaliation. The majority opinion by Justice Clarence Thomas found the statute of limitations \"ambiguous.\" The ambiguity arose from the fact that the six-year limitation in the FCA starts from the time the false claim was made. Yet in a retaliation suit, no actual false claim needs to be alleged.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"Green v. Brennan","cite":"578 U.S. 547","y":2016,"id":"2015/14-613","sc":1,"op":1,"sum":"The Court held that the 45-day period in which an employee must file a constructive discharge claim under federal employment discrimination law begins to run on the date the employee resigns.","sumSrc":"Oyez","by":{"0":"26","2":"21, 24"}},{"t":"case","label":"Groff v. DeJoy","cite":"600 U.S. 447","y":2023,"id":"2022/22-174","sc":1,"sum":"Title VII requires an employer that denies a religious accommodation to show that the burden of granting an accommodation would result in substantial increased costs in relation to the conduct of its particular business.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"17"}},{"t":"case","label":"Heredia v. Sessions","cite":"865 F.3d 60","y":2017,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/865/60/","sum":"Explaining that “a restrictive clause” that modifies a noun in an immigration statute “does not impose a separate temporal requirement”.","sumSrc":"brief:0","by":{"0":"41"}},{"t":"case","label":"Hishon v. King & Spalding","cite":"467 U.S. 69","y":1984,"id":"1983/82-940","sc":1,"op":3,"ar":1,"sum":"The Court held that Title VII makes it illegal for an employer to discriminate against any employee on the basis of their sex. In this case, the Court held that the promise of equal consideration for partnership that went along with Hishon’s employment was contractual in nature and subject to the regulations of Title VII.","sumSrc":"Oyez","by":{"0":"2, 6, 19, 29","1":"20, 29, 30","3":"12"}},{"t":"case","label":"Howard Delivery Service, Inc. v. Zurich American Insurance Co.","cite":"547 U.S. 651","y":2006,"id":"2005/05-128","sc":1,"sum":"In a 6-to-3 decision authored by Justice Ruth Bader Ginsburg, the Supreme Court held that the workers' compensation insurance was different from the sort of employee benefit programs for which creditors could be given priority under Chapter 11. The programs for which preferred status was authorized were those whose main beneficiaries were the employees, and which could be offered as an alternative to wage increases.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"- vi - Kincaid v. Williams","cite":"143 S. Ct. 2414","y":2023,"url":"https://www.courtlistener.com/c/S.%20Ct./143/2414/","sc":1,"by":{"0":"30","2":"2"}},{"t":"case","label":"Ledbetter v. Goodyear Tire & Rubber Co.","cite":"550 U.S. 618","y":2007,"id":"2006/05-1074","sc":1,"op":1,"ar":1,"sum":"The Court ruled that a plaintiff cannot bring a salary discrimination suit under Title VII of the Civil Rights Act when the disparate pay is the result of decisions made outside of the 180-day limitations period.","sumSrc":"Oyez","by":{"0":"22","1":"14, 19","2":"25","3":"6"}},{"t":"case","label":"Lexmark International, Inc. v. Static Control Components, Inc.","cite":"572 U.S. 118","y":2014,"id":"2013/12-873","sc":1,"sum":"The Court held that the Lanham Act allowed any party to sue for injuries relating to false advertising, as long as the party bringing suit has an interest that falls in the zone of interest that is protected by law.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Lightfoot v. Cendant Mortgage Corp.","cite":"580 U.S. 82","y":2017,"id":"2016/14-1055","sc":1,"sum":"The Court determined that language in the federal charter of the Federal National Mortgage Association (Fannie Mae) that authorizes the organization to sue and be sued does not mean that federal courts have subject matter jurisdiction over any case in which Fannie Mae is a plaintiff or defendant, and the Supreme Court’s precedent in American National Red Cross v. S.G. doe not require a different result.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Match-E-Be-Nash-She-Wish Band of Pottawatomi Indians v. Patchak","cite":"567 U.S. 209","y":2012,"id":"2011/11-246","sc":1,"sum":"The Court held that a neighbor of a proposed Indian casino had standing to sue the government for taking 147 acres of a town's land under Section 465 of the Indian Reorganization Act.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"New York State Department of Social Services v. Dublino","cite":"413 U.S. 405","y":1973,"id":"1972/72-792","sc":1,"sum":"The 1967 amendments to the Social Security Act included the Federal Work Incentive Program (WIN), designed to help individuals on welfare become wage-earning members of society. The States were required to incorporate this program into their Aid to Families With Dependent Children (AFDC) program, to provide that certain \"employable\" individuals, as a condition for receiving aid, shall register for manpower services, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47"}},{"t":"case","label":"Nielsen v. Preap","cite":"586 U.S. 392","y":2019,"id":"2018/16-1363","sc":1,"op":1,"sum":"The Ninth Circuit’s judgments—that respondents, who are deportable for certain specified crimes, are not subject to 8 U. S. C. §1226(c)(2)’s mandatory-detention requirement because they were not arrested by immigration officials as soon as they were released from jail—are reversed, and the cases are remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"40"}},{"t":"case","label":"Parker Drilling Management Services, Ltd. v. Newton","cite":"587 U.S. 601","y":2019,"id":"2018/18-389","sc":1,"sum":"Under the Outer Continental Shelf Lands Act, where federal law addresses the relevant issue, state law is not adopted as surrogate federal law on the Outer Continental Shelf.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"32"}},{"t":"case","label":"Pereira v. Sessions","cite":"585 U.S. 198","y":2018,"id":"2017/17-459","sc":1,"sum":"The Court held that a notice to appear for a removal hearing that does not specify the place and time of the hearing does not trigger the stop-time rule of 8 U.S.C. § 1229b(b)(1), which gives the attorney general discretion to cancel removal for an alien who, among other criteria, has been continuously physically present in the country for at least ten years.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"PGA Tour, Inc. v. Martin","cite":"532 U.S. 661","y":2001,"id":"2000/00-24","sc":1,"op":1,"sum":"The Court held that Title III of the ADA, by its plain terms, prohibits the PGA from denying Martin equal access to its tours on the basis of his disability and that allowing Martin to use a cart, despite the walking rule, is not a modification that would \"fundamentally alter the nature\" of the game. \"The purpose of the walking rule is... not compromised in the slightest by allowing Martin to use a cart,\" wrote Justice Stevens, noting Martin's fatiguing disability.","sumSrc":"Oyez","by":{"0":"5, 6, 17","1":"2"}},{"t":"case","label":"Pulsifer v. United States","cite":"601 U.S. 124","y":2024,"id":"2023/22-340","sc":1,"sum":"A criminal defendant facing a mandatory minimum sentence is eligible for safety-valve relief under 18 U. S. C. §3553(f)(1) only if the defendant satisfies each of the provision’s three conditions.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"4, 16, 44, 45, 46"}},{"t":"case","label":"- vii - Raytheon Co. v. Hernandez","cite":"540 U.S. 44","y":2003,"id":"2003/02-749","sc":1,"op":1,"sum":"The Court unanimously held that an employer may refuse to rehire an employee who was terminated in connection with drug or alcohol-related incidents as long as the refusal is based on a policy of not rehiring employees who previously violated workplace rules rather than on the worker's addiction.","sumSrc":"Oyez","by":{"0":"29","1":"14"}},{"t":"case","label":"Robinson v. Shell Oil Co.","cite":"519 U.S. 337","y":1997,"id":"1996/95-1376","sc":1,"op":6,"sum":"Authored by Justice Clarence Thomas, the Court ruled that because the term \"employees,\" as used Title VII of the Civil Rights Act of 1964, includes former employees, Robinson may sue Shell for its allegedly retaliatory post-employment actions.","sumSrc":"Oyez","by":{"0":"1, 16, 35, 46, 47","1":"13","2":"28, 30, 32, 36","3":"17"}},{"t":"case","label":"Rubin v. Islamic Republic of Iran","cite":"583 U.S. 202","y":2018,"id":"2017/16-534","sc":1,"sum":"The Court held that 28 U.S.C. § 1610(g) does not provide a freestanding attachment immunity exception that allows terror victim judgment creditors to attach and execute upon assets of foreign state; rather, the immunity of property must be rescinded under a separate provision under that section.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Thompson v. North American Stainless, LP","cite":"562 U.S. 170","y":2011,"id":"2010/09-291","sc":1,"sum":"The Court held that an employer violates Title VII of the Civil Rights Acts by firing the fiancee of an employee who complains about workplace discrimination.","sumSrc":"Oyez","by":{"0":"18","2":"19"}},{"t":"case","label":"Torres v. Lynch","cite":"578 U.S. 452","y":2016,"id":"2015/14-1096","sc":1,"sum":"The Court determined that a state offense may constitute an aggravated felony for the purpose of the removal of a permanent resident when it includes all the elements of the federal statute with the exception of the interstate commerce element.","sumSrc":"Oyez","by":{"0":"44","3":"11"}},{"t":"case","label":"UAW v. Johnson Controls, Inc.","cite":"499 U.S. 187","y":1991,"id":"1990/89-1215","sc":1,"sum":"The Court noted that even well intentioned proposals are forbidden if they result in discrimination. Johnson's fetal-protection plan discriminated against women by not requiring their male counterparts to demonstrate proof of medical sterility, despite the fact that lead exposure has also proved hazardous to male reproductive systems.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"United States v. Georgia","cite":"546 U.S. 151","y":2006,"id":"2005/04-1203","sc":1,"sum":"The Court ruled that Title II abrogates sovereign immunity in cases where violations of the 8th Amendment are alleged. The 14th Amendment incorporates the 8th Amendment (that is, applies it to the states).","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"United States v. Shkambi","cite":"993 F.3d 388","y":2021,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/993/388/","by":{"0":"39"}},{"t":"case","label":"US Airways, Inc. v. Barnett","cite":"535 U.S. 391","y":2002,"id":"2001/00-1250","sc":1,"sum":"The Court held that the ADA did not require the employer to assign the employee to the mailroom position in violation of the established seniority system. The Court reasoned that an employer's showing that a requested accommodation conflicts with seniority rules is ordinarily sufficient to show that an accommodation is not reasonable.","sumSrc":"Oyez","by":{"0":"7, 30, 46","1":"14","3":"13"}},{"t":"case","label":"Whitman v. American Trucking Associations","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"Chiaverini v. City of Napoleon","cite":"144 S. Ct. 1745","y":2024,"id":"2023/23-50","sc":1,"sum":"Pursuant to the Fourth Amendment and traditional common-law practice, the presence of probable cause for one charge in a criminal proceeding does not categorically defeat a Fourth Amendment malicious-prosecution claim relating to another, baseless charge.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"18","3":"20"}},{"t":"case","label":"Davis v. Michigan Dep’t of the Treas.","cite":"489 U.S. 803","y":1989,"id":"1988/87-1020","sc":1,"op":1,"sum":"Interpreting statute that consented to state “ `taxation of pay or compensation for personal service as an offcer or employee of the United States' ” to cover federal retirement benefts, because they are compensation for service as a federal employee.","sumSrc":"opinion","by":{"1":"29, 30","3":"3, 8, 11, 12"}},{"t":"case","label":"District of Columbia v. Greater Wash. Bd. of Trade","cite":"506 U.S. 125","y":1992,"id":"1992/91-1326","sc":1,"sum":"Section 2(c)(2) is pre-empted by ERISA. A state law \"relate[s] to\" a covered benefit plan for § 514(a) purposes if it refers to or has a connection with such a plan, even if the law is not designed to affect the plan or the effect is only indirect. See, e. g., Ingersoll-RandCo. v. McClendon, 498 U. S. 133, 139. Section 2(c)(2) measures the required health care coverage by reference to \"the existing health insurance …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"EEOC v. Commercial Office Prods. Co.","cite":"486 U.S. 107","y":1988,"id":"1987/86-1696","sc":1,"sum":"The judgment is reversed, and the case is remanded. 803 F. 2d 581, reversed and remanded. JUSTICE MARSHALL delivered the opinion of the Court with respect to Parts I, II-A, and III, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"3"}},{"t":"case","label":"Gonzales v. Garner Food Servs., Inc.","cite":"89 F.3d 1523","y":1996,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/89/1523/","by":{"1":"6"}},{"t":"case","label":"Intel Corp. Inv. Policy Comm. v. Sulyma","cite":"589 U.S. 178","y":2020,"id":"2019/18-1116","sc":1,"sum":"The Court held that under the Employee Retirement Income Security Act of 1974 requirement that plaintiffs with “actual knowledge” of an alleged fiduciary breach must file suit within three years of gaining that knowledge, a plaintiff does not necessarily have “actual knowledge” of the information contained in disclosures that he receives but does not read or cannot recall reading.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"Lebron v. National R.R. Passenger Corp.","cite":"513 U.S. 374","y":1995,"id":"1994/93-1525","sc":1,"op":2,"sum":"Where, as here, the Government creates a corporation by special law, for the furtherance of governmental objectives, and retains for itself permanent authority to appoint a majority of that corporation's directors, the corporation is part of the Government for purposes of the First Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28","3":"19"}},{"t":"case","label":"Mazzeo v. Color Resolutions Int’l, LLC","cite":"746 F.3d 1264","y":2014,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/746/1264/","by":{"1":"24"}},{"t":"case","label":"National R.R. Passenger Corp. v. Morgan","cite":"536 U.S. 101","y":2002,"id":"2001/00-1614","sc":1,"sum":"The Court held that Title VII of the Civil Rights Act of 1964 precludes recovery for discrete acts of discrimination or retaliation that occur outside the statutory time period.","sumSrc":"Oyez","by":{"1":"15"}},{"t":"case","label":"Newport News Shipbuilding & Dry Dock Co. v. EEOC","cite":"462 U.S. 669","y":1983,"id":"1982/82-411","sc":1,"op":1,"sum":"The pregnancy limitation in petitioner's amended health plan discriminates against male employees in violation of § 703(a)(1).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"United States v. Williams","cite":"504 U.S. 36","y":1992,"id":"1991/90-1972","sc":1,"op":1,"sum":"Respondent Williams was indicted by a federal grand jury for alleged violations of 18 U. S. C. § 1014. On his motion, the District Court ordered the indictment dismissed without prejudice because the Government had failed to fulfill its obligation under Circuit precedent to present \"substantial exculpatory evidence\" to the grand jury. Following that precedent, the Court of Appeals affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28"}},{"t":"case","label":"Wilkinson v. Garland","cite":"601 U.S. 209","y":2024,"id":"2023/22-666","sc":1,"op":1,"sum":"The Immigration Judge’s discretionary decision that Mr. Wilkinson failed to satisfy 8 U. S. C. §1229b(b)(1)(D)’s “exceptional and extremely unusual” hardship standard for determining eligibility for cancellation of removal is a mixed question of law and fact, reviewable under §1252(a)(2)(D)’s jurisdiction restoring exception for “questions of law”; the Third Circuit’s holding that the IJ’s decision was unreviewable under §1252(a)(2)(B)(i) was in error.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"24"}},{"t":"case","label":"Yee v. Escondido","cite":"503 U.S. 519","y":1992,"id":"1991/90-1947","sc":1,"op":3,"sum":"The Fifth Amendment's Takings Clause generally requires just compensation where the government authorizes a physical occupation of property. But where the government merely regulates the property's use, compensation is required only if considerations such as the regulation's purpose or the extent to which it deprives the owner of the property's economic use suggests that the regulation has unfairly singled out the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28","2":"15"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"1":"25"}},{"t":"law","label":"Pub. L. No. 110-325","url":"https://www.govinfo.gov/link/plaw/110/public/325","by":{"1":"2","2":"20, 29"}},{"t":"usc","label":"42 U.S.C. § 12101","url":"https://www.law.cornell.edu/uscode/text/42/12101","subs":["(a)(5)","(b)(1)","(b)(4)","(8)","(a)(2)","(a)(4)"],"stext":{"head":"§12101. Findings and purpose","paras":[[0,"(a) Findings"],[0,"The Congress finds that—"],[1,"(1) physical or mental disabilities in no way diminish a person's right to fully participate in all aspects of society, yet many people with physical or mental disabilities have been precluded from doing so because of discrimination; others who have a record of a disability or are regarded as having a disability also have been subjected to discrimination;"],[1,"(2) historically, society has tended to isolate and segregate individuals with disabilities, and, despite some improvements, such forms of discrimination against individuals with disabilities continue to be a serious and pervasive social problem;"],[1,"(3) discrimination against individuals with disabilities persists in such critical areas as employment, housing, public accommodations, education, transportation, communication, recreation, institutionalization, health services, voting, and access to public services;"],[1,"(4) unlike individuals who have experienced discrimination on the basis of race, color, sex, national origin, religion, or age, individuals who have experienced discrimination on the basis of disability have often had no legal recourse to redress such discrimination;"],[1,"(5) individuals with disabilities continually encounter various forms of discrimination, including outright intentional exclusion, the discriminatory effects of architectural, transportation, and communication barriers, overprotective rules and policies, failure to make modifications to existing facilities and practices, exclusionary qualification standards and criteria, segregation, and relegation to lesser services, programs, activities, benefits, jobs, or other opportunities;"],[1,"(6) census data, national polls, and other studies have documented that people with disabilities, as a group, occupy an inferior status in our society, and are severely disadvantaged socially, vocationally, economically, and educationally;"],[1,"(7) the Nation's proper goals regarding individuals with disabilities are to assure equality of opportunity, full participation, independent living, and economic self-sufficiency for such individuals; and"],[1,"(8) the continuing existence of unfair and unnecessary discrimination and prejudice denies people with disabilities the opportunity to compete on an equal basis and to pursue those opportunities for which our free society is justifiably famous, and costs the United States billions of dollars in unnecessary expenses resulting from dependency and nonproductivity."],[0,"(b) Purpose"],[0,"It is the purpose of this chapter—"],[1,"(1) to provide a clear and comprehensive national mandate for the elimination of discrimination against individuals with disabilities;"],[1,"(2) to provide clear, strong, consistent, enforceable standards addressing discrimination against individuals with disabilities;"],[1,"(3) to ensure that the Federal Government plays a central role in enforcing the standards established in this chapter on behalf of individuals with disabilities; and"],[1,"(4) to invoke the sweep of congressional authority, including the power to enforce the fourteenth amendment and to regulate commerce, in order to address the major areas of discrimination faced day-to-day by people with disabilities."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/12101?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§12101. Findings and purpose","tname":"The Public Health and Welfare","by":{"1":"1, 2, 1, 2, 3, 5, 6, 8-14, 17, 20-24, 28, 29, 31, 1, 2, 3, 5, 6, 8-14, 17, 20-24, 28, 29, 31, 1, 2, 3, 5, 6, 8-14, 17, 20-24, 28, 29, 31","2":"34, 3, 3, 50","3":"15"}},{"t":"usc","label":"42 U.S.C. § 12102","url":"https://www.law.cornell.edu/uscode/text/42/12102","subs":["(1)","(3)","(1)(C)"],"stext":{"head":"§12102. Definition of disability","paras":[[0,"As used in this chapter:"],[0,"(1) Disability"],[1,"The term \"disability\" means, with respect to an individual—"],[2,"(A) a physical or mental impairment that substantially limits one or more major life activities of such individual;"],[2,"(B) a record of such an impairment; or"],[2,"(C) being regarded as having such an impairment (as described in paragraph (3))."],[0,"(2) Major life activities"],[0,"(A) In general"],[2,"For purposes of paragraph (1), major life activities include, but are not limited to, caring for oneself, performing manual tasks, seeing, hearing, eating, sleeping, walking, standing, lifting, bending, speaking, breathing, learning, reading, concentrating, thinking, communicating, and working."],[0,"(B) Major bodily functions"],[2,"For purposes of paragraph (1), a major life activity also includes the operation of a major bodily function, including but not limited to, functions of the immune system, normal cell growth, digestive, bowel, bladder, neurological, brain, respiratory, circulatory, endocrine, and reproductive functions."],[0,"(3) Regarded as having such an impairment"],[1,"For purposes of paragraph (1)(C):"],[2,"(A) An individual meets the requirement of \"being regarded as having such an impairment\" if the individual establishes that he or she has been subjected to an action prohibited under this chapter because of an actual or perceived physical or mental impairment whether or not the impairment limits or is perceived to limit a major life activity."],[2,"(B) Paragraph (1)(C) shall not apply to impairments that are transitory and minor. A transitory impairment is an impairment with an actual or expected duration of 6 months or less."],[0,"(4) Rules of construction regarding the definition of disability"],[1,"The definition of \"disability\" in paragraph (1) shall be construed in accordance with the following:"],[2,"(A) The definition of disability in this chapter shall be construed in favor of broad coverage of individuals under this chapter, to the maximum extent permitted by the terms of this chapter."],[2,"(B) The term \"substantially limits\" shall be interpreted consistently with the findings and purposes of the ADA Amendments Act of 2008."],[2,"(C) An impairment that substantially limits one major life activity need not limit other major life activities in order to be considered a disability."],[2,"(D) An impairment that is episodic or in remission is a disability if it would substantially limit a major life activity when active."],[2,"(E)(i) The determination of whether an impairment substantially limits a major life activity shall be made without regard to the ameliorative effects of mitigating measures such as—"],[3,"(I) medication, medical supplies, equipment, or appliances, low-vision devices (which do not include ordinary eyeglasses or contact lenses), prosthetics including limbs and devices, hearing aids and cochlear implants or other implantable hearing devices, mobility devices, or oxygen therapy equipment and supplies;"],[3,"(II) use of assistive technology;"],[3,"(III) reasonable accommodations or auxiliary aids or services; or"],[3,"(IV) learned behavioral or adaptive neurological modifications."],[2,"(ii) The ameliorative effects of the mitigating measures of ordinary eyeglasses or contact lenses shall be considered in determining whether an impairment substantially limits a major life activity."],[2,"(iii) As used in this subparagraph—"],[3,"(I) the term \"ordinary eyeglasses or contact lenses\" means lenses that are intended to fully correct visual acuity or eliminate refractive error; and"],[3,"(II) the term \"low-vision devices\" means devices that magnify, enhance, or otherwise augment a visual image."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/12102?type=usc&year=mostrecent&link-type=html"},"head":"§12102. Definition of disability","tname":"The Public Health and Welfare","by":{"1":"1, 2, 3, 5, 6, 8-14, 17, 20-24, 28, 29, 31, 1, 2, 3, 5, 6, 8-14, 17, 20-24, 28, 29, 31","2":"19"}},{"t":"usc","label":"42 U.S.C. § 12111","url":"https://www.law.cornell.edu/uscode/text/42/12111","subs":["(2)","(8)"],"stext":{"head":"§12111. Definitions","paras":[[0,"As used in this subchapter:"],[0,"(1) Commission"],[1,"The term \"Commission\" means the Equal Employment Opportunity Commission established by section 2000e–4 of this title."],[0,"(2) Covered entity"],[1,"The term \"covered entity\" means an employer, employment agency, labor organization, or joint labor-management committee."],[0,"(3) Direct threat"],[1,"The term \"direct threat\" means a significant risk to the health or safety of others that cannot be eliminated by reasonable accommodation."],[0,"(4) Employee"],[1,"The term \"employee\" means an individual employed by an employer. With respect to employment in a foreign country, such term includes an individual who is a citizen of the United States."],[0,"(5) Employer"],[0,"(A) In general"],[2,"The term \"employer\" means a person engaged in an industry affecting commerce who has 15 or more employees for each working day in each of 20 or more calendar weeks in the current or preceding calendar year, and any agent of such person, except that, for two years following the effective date of this subchapter, an employer means a person engaged in an industry affecting commerce who has 25 or more employees for each working day in each of 20 or more calendar weeks in the current or preceding year, and any agent of such person."],[0,"(B) Exceptions"],[2,"The term \"employer\" does not include—"],[3,"(i) the United States, a corporation wholly owned by the government of the United States, or an Indian tribe; or"],[3,"(ii) a bona fide private membership club (other than a labor organization) that is exempt from taxation under section 501(c) of title 26."],[0,"(6) Illegal use of drugs"],[0,"(A) In general"],[2,"The term \"illegal use of drugs\" means the use of drugs, the possession or distribution of which is unlawful under the Controlled Substances Act [21 U.S.C. 801 et seq.]. Such term does not include the use of a drug taken under supervision by a licensed health care professional, or other uses authorized by the Controlled Substances Act or other provisions of Federal law."],[0,"(B) Drugs"],[2,"The term \"drug\" means a controlled substance, as defined in schedules I through V of section 202 of the Controlled Substances Act [21 U.S.C. 812]."],[0,"(7) Person, etc."],[1,"The terms \"person\", \"labor organization\", \"employment agency\", \"commerce\", and \"industry affecting commerce\", shall have the same meaning given such terms in section 2000e of this title."],[0,"(8) Qualified individual"],[1,"The term \"qualified individual\" means an individual who, with or without reasonable accommodation, can perform the essential functions of the employment position that such individual holds or desires. For the purposes of this subchapter, consideration shall be given to the employer's judgment as to what functions of a job are essential, and if an employer has prepared a written description before advertising or interviewing applicants for the job, this description shall be considered evidence of the essential functions of the job."],[0,"(9) Reasonable accommodation"],[1,"The term \"reasonable accommodation\" may include—"],[2,"(A) making existing facilities used by employees readily accessible to and usable by individuals with disabilities; and"],[2,"(B) job restructuring, part-time or modified work schedules, reassignment to a vacant position, acquisition or modification of equipment or devices, appropriate adjustment or modifications of examinations, training materials or policies, the provision of qualified readers or interpreters, and other similar accommodations for individuals with disabilities."],[0,"(10) Undue hardship"],[0,"(A) In general"],[2,"The term \"undue hardship\" means an action requiring significant difficulty or expense, when considered in light of the factors set forth in subparagraph (B)."],[0,"(B) Factors to be considered"],[2,"In determining whether an accommodation would impose an undue hardship on a covered entity, factors to be considered include—"],[3,"(i) the nature and cost of the accommodation needed under this chapter;"],[3,"(ii) the overall financial resources of the facility or facilities involved in the provision of the reasonable accommodation; the number of persons employed at such facility; the effect on expenses and resources, or the impact otherwise of such accommodation upon the operation of the facility;"],[3,"(iii) the overall financial resources of the covered entity; the overall size of the business of a covered entity with respect to the number of its employees; the number, type, and location of its facilities; and"],[3,"(iv) the type of operation or operations of the covered entity, including the composition, structure, and functions of the workforce of such entity; the geographic separateness, administrative, or fiscal relationship of the facility or facilities in question to the covered entity."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/12111?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§12111. Definitions","tname":"The Public Health and Welfare","by":{"1":"1, 2, 3, 5, 6, 8-14, 17, 20-24, 28, 29, 31, 2, 2","2":"4, 28-30, 32, 33, 39, 42, 43, 48","3":"12"}},{"t":"usc","label":"42 U.S.C. § 12112","url":"https://www.law.cornell.edu/uscode/text/42/12112","subs":["(a)","(b)","(b)(1)","(b)(2)","(b)(4)","(b)(5)","(b)(6)"],"stext":{"head":"§12112. Discrimination","paras":[[0,"(a) General rule"],[0,"No covered entity shall discriminate against a qualified individual on the basis of disability in regard to job application procedures, the hiring, advancement, or discharge of employees, employee compensation, job training, and other terms, conditions, and privileges of employment."],[0,"(b) Construction"],[0,"As used in subsection (a), the term \"discriminate against a qualified individual on the basis of disability\" includes—"],[1,"(1) limiting, segregating, or classifying a job applicant or employee in a way that adversely affects the opportunities or status of such applicant or employee because of the disability of such applicant or employee;"],[1,"(2) participating in a contractual or other arrangement or relationship that has the effect of subjecting a covered entity's qualified applicant or employee with a disability to the discrimination prohibited by this subchapter (such relationship includes a relationship with an employment or referral agency, labor union, an organization providing fringe benefits to an employee of the covered entity, or an organization providing training and apprenticeship programs);"],[1,"(3) utilizing standards, criteria, or methods of administration—"],[2,"(A) that have the effect of discrimination on the basis of disability; or"],[2,"(B) that perpetuate the discrimination of others who are subject to common administrative control;"],[1,"(4) excluding or otherwise denying equal jobs or benefits to a qualified individual because of the known disability of an individual with whom the qualified individual is known to have a relationship or association;"],[1,"(5)(A) not making reasonable accommodations to the known physical or mental limitations of an otherwise qualified individual with a disability who is an applicant or employee, unless such covered entity can demonstrate that the accommodation would impose an undue hardship on the operation of the business of such covered entity; or"],[1,"(B) denying employment opportunities to a job applicant or employee who is an otherwise qualified individual with a disability, if such denial is based on the need of such covered entity to make reasonable accommodation to the physical or mental impairments of the employee or applicant;"],[1,"(6) using qualification standards, employment tests or other selection criteria that screen out or tend to screen out an individual with a disability or a class of individuals with disabilities unless the standard, test or other selection criteria, as used by the covered entity, is shown to be job-related for the position in question and is consistent with business necessity; and"],[1,"(7) failing to select and administer tests concerning employment in the most effective manner to ensure that, when such test is administered to a job applicant or employee who has a disability that impairs sensory, manual, or speaking skills, such test results accurately reflect the skills, aptitude, or whatever other factor of such applicant or employee that such test purports to measure, rather than reflecting the impaired sensory, manual, or speaking skills of such employee or applicant (except where such skills are the factors that the test purports to measure)."],[0,"(c) Covered entities in foreign countries"],[0,"(1) In general"],[1,"It shall not be unlawful under this section for a covered entity to take any action that constitutes discrimination under this section with respect to an employee in a workplace in a foreign country if compliance with this section would cause such covered entity to violate the law of the foreign country in which such workplace is located."],[0,"(2) Control of corporation"],[0,"(A) Presumption"],[2,"If an employer controls a corporation whose place of incorporation is a foreign country, any practice that constitutes discrimination under this section and is engaged in by such corporation shall be presumed to be engaged in by such employer."],[0,"(B) Exception"],[2,"This section shall not apply with respect to the foreign operations of an employer that is a foreign person not controlled by an American employer."],[0,"(C) Determination"],[2,"For purposes of this paragraph, the determination of whether an employer controls a corporation shall be based on—"],[3,"(i) the interrelation of operations;"],[3,"(ii) the common management;"],[3,"(iii) the centralized control of labor relations; and"],[3,"(iv) the common ownership or financial control,"],[2,"of the employer and the corporation."],[0,"(d) Medical examinations and inquiries"],[0,"(1) In general"],[1,"The prohibition against discrimination as referred to in subsection (a) shall include medical examinations and inquiries."],[0,"(2) Preemployment"],[0,"(A) Prohibited examination or inquiry"],[2,"Except as provided in paragraph (3), a covered entity shall not conduct a medical examination or make inquiries of a job applicant as to whether such applicant is an individual with a disability or as to the nature or severity of such disability."],[0,"(B) Acceptable inquiry"],[2,"A covered entity may make preemployment inquiries into the ability of an applicant to perform job-related functions."],[0,"(3) Employment entrance examination"],[1,"A covered entity may require a medical examination after an offer of employment has been made to a job applicant and prior to the commencement of the employment duties of such applicant, and may condition an offer of employment on the results of such examination, if—"],[2,"(A) all entering employees are subjected to such an examination regardless of disability;"],[2,"(B) information obtained regarding the medical condition or history of the applicant is collected and maintained on separate forms and in separate medical files and is treated as a confidential medical record, except that—"],[3,"(i) supervisors and managers may be informed regarding necessary restrictions on the work or duties of the employee and necessary accommodations;"],[3,"(ii) first aid and safety personnel may be informed, when appropriate, if the disability might require emergency treatment; and"],[3,"(iii) government officials investigating compliance with this chapter shall be provided relevant information on request; and"],[2,"(C) the results of such examination are used only in accordance with this subchapter."],[0,"(4) Examination and inquiry"],[0,"(A) Prohibited examinations and inquiries"],[2,"A covered entity shall not require a medical examination and shall not make inquiries of an employee as to whether such employee is an individual with a disability or as to the nature or severity of the disability, unless such examination or inquiry is shown to be job-related and consistent with business necessity."],[0,"(B) Acceptable examinations and inquiries"],[2,"A covered entity may conduct voluntary medical examinations, including voluntary medical histories, which are part of an employee health program available to employees at that work site. A covered entity may make inquiries into the ability of an employee to perform job-related functions."],[0,"(C) Requirement"],[2,"Information obtained under subparagraph (B) regarding the medical condition or history of any employee are subject to the requirements of subparagraphs (B) and (C) of paragraph (3)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/12112?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§12112. Discrimination","tname":"The Public Health and Welfare","by":{"1":"2, 2, 2, 2, 2, 2, 2, 2","2":"42, 4, 11, 15, 19, 20, 28-30, 32, 33, 35, 39, 47, 3, 19, 20, 42-44","3":"4, 13, 14"}},{"t":"usc","label":"42 U.S.C. § 12117","url":"https://www.law.cornell.edu/uscode/text/42/12117","subs":["(a)"],"stext":{"head":"§12117. Enforcement","paras":[[0,"(a) Powers, remedies, and procedures"],[0,"The powers, remedies, and procedures set forth in sections 2000e–4, 2000e–5, 2000e–6, 2000e–8, and 2000e–9 of this title shall be the powers, remedies, and procedures this subchapter provides to the Commission, to the Attorney General, or to any person alleging discrimination on the basis of disability in violation of any provision of this chapter, or regulations promulgated under section 12116 of this title, concerning employment."],[0,"(b) Coordination"],[0,"The agencies with enforcement authority for actions which allege employment discrimination under this subchapter and under the Rehabilitation Act of 1973 [29 U.S.C. 701 et seq.] shall develop procedures to ensure that administrative complaints filed under this subchapter and under the Rehabilitation Act of 1973 are dealt with in a manner that avoids duplication of effort and prevents imposition of inconsistent or conflicting standards for the same requirements under this subchapter and the Rehabilitation Act of 1973. The Commission, the Attorney General, and the Office of Federal Contract Compliance Programs shall establish such coordinating mechanisms (similar to provisions contained in the joint regulations promulgated by the Commission and the Attorney General at part 42 of title 28 and part 1691 of title 29, Code of Federal Regulations, and the Memorandum of Understanding between the Commission and the Office of Federal Contract Compliance Programs dated January 16, 1981 (46 Fed. Reg. 7435, January 23, 1981)) in regulations implementing this subchapter and Rehabilitation Act of 1973 not later than 18 months after July 26, 1990."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/12117?type=usc&year=mostrecent&link-type=html"},"head":"§12117. Enforcement","tname":"The Public Health and Welfare","by":{"1":"2, 2","2":"11, 18"}},{"t":"usc","label":"42 U.S.C. § 12131","url":"https://www.law.cornell.edu/uscode/text/42/12131","by":{"1":"2"}},{"t":"usc","label":"42 U.S.C. § 12181","url":"https://www.law.cornell.edu/uscode/text/42/12181","by":{"1":"2"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","stext":{"head":"§2000e. Definitions","paras":[[0,"For the purposes of this subchapter—"],[1,"(a) The term \"person\" includes one or more individuals, governments, governmental agencies, political subdivisions, labor unions, partnerships, associations, corporations, legal representatives, mutual companies, joint-stock companies, trusts, unincorporated organizations, trustees, trustees in cases under title 11, or receivers."],[1,"(b) The term \"employer\" means a person engaged in an industry affecting commerce who has fifteen or more employees for each working day in each of twenty or more calendar weeks in the current or preceding calendar year, and any agent of such a person, but such term does not include (1) the United States, a corporation wholly owned by the Government of the United States, an Indian tribe, or any department or agency of the District of Columbia subject by statute to procedures of the competitive service (as defined in section 2102 of title 5), or (2) a bona fide private membership club (other than a labor organization) which is exempt from taxation under section 501(c) of title 26, except that during the first year after March 24, 1972, persons having fewer than twenty-five employees (and their agents) shall not be considered employers."],[1,"(c) The term \"employment agency\" means any person regularly undertaking with or without compensation to procure employees for an employer or to procure for employees opportunities to work for an employer and includes an agent of such a person."],[1,"(d) The term \"labor organization\" means a labor organization engaged in an industry affecting commerce, and any agent of such an organization, and includes any organization of any kind, any agency, or employee representation committee, group, association, or plan so engaged in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning grievances, labor disputes, wages, rates of pay, hours, or other terms or conditions of employment, and any conference, general committee, joint or system board, or joint council so engaged which is subordinate to a national or international labor organization."],[1,"(e) A labor organization shall be deemed to be engaged in an industry affecting commerce if (1) it maintains or operates a hiring hall or hiring office which procures employees for an employer or procures for employees opportunities to work for an employer, or (2) the number of its members (or, where it is a labor organization composed of other labor organizations or their representatives, if the aggregate number of the members of such other labor organization) is (A) twenty-five or more during the first year after March 24, 1972, or (B) fifteen or more thereafter, and such labor organization—"],[2,"(1) is the certified representative of employees under the provisions of the National Labor Relations Act, as amended [29 U.S.C. 151 et seq.], or the Railway Labor Act, as amended [45 U.S.C. 151 et seq.];"],[2,"(2) although not certified, is a national or international labor organization or a local labor organization recognized or acting as the representative of employees of an employer or employers engaged in an industry affecting commerce; or"],[2,"(3) has chartered a local labor organization or subsidiary body which is representing or actively seeking to represent employees of employers within the meaning of paragraph (1) or (2); or"],[2,"(4) has been chartered by a labor organization representing or actively seeking to represent employees within the meaning of paragraph (1) or (2) as the local or subordinate body through which such employees may enjoy membership or become affiliated with such labor organization; or"],[2,"(5) is a conference, general committee, joint or system board, or joint council subordinate to a national or international labor organization, which includes a labor organization engaged in an industry affecting commerce within the meaning of any of the preceding paragraphs of this subsection."],[1,"(f) The term \"employee\" means an individual employed by an employer, except that the term \"employee\" shall not include any person elected to public office in any State or political subdivision of any State by the qualified voters thereof, or any person chosen by such officer to be on such officer's personal staff, or an appointee on the policy making level or an immediate adviser with respect to the exercise of the constitutional or legal powers of the office. The exemption set forth in the preceding sentence shall not include employees subject to the civil service laws of a State government, governmental agency or political subdivision. With respect to employment in a foreign country, such term includes an individual who is a citizen of the United States."],[1,"(g) The term \"commerce\" means trade, traffic, commerce, transportation, transmission, or communication among the several States; or between a State and any place outside thereof; or within the District of Columbia, or a possession of the United States; or between points in the same State but through a point outside thereof."],[1,"(h) The term \"industry affecting commerce\" means any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce and includes any activity or industry \"affecting commerce\" within the meaning of the Labor-Management Reporting and Disclosure Act of 1959 [29 U.S.C. 401 et seq.], and further includes any governmental industry, business, or activity."],[1,"(i) The term \"State\" includes a State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, American Samoa, Guam, Wake Island, the Canal Zone, and Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act [43 U.S.C. 1331 et seq.]."],[1,"(j) The term \"religion\" includes all aspects of religious observance and practice, as well as belief, unless an employer demonstrates that he is unable to reasonably accommodate to an employee's or prospective employee's religious observance or practice without undue hardship on the conduct of the employer's business."],[1,"(k) The terms \"because of sex\" or \"on the basis of sex\" include, but are not limited to, because of or on the basis of pregnancy, childbirth, or related medical conditions; and women affected by pregnancy, childbirth, or related medical conditions shall be treated the same for all employment-related purposes, including receipt of benefits under fringe benefit programs, as other persons not so affected but similar in their ability or inability to work, and nothing in section 2000e–2(h) of this title shall be interpreted to permit otherwise. This subsection shall not require an employer to pay for health insurance benefits for abortion, except where the life of the mother would be endangered if the fetus were carried to term, or except where medical complications have arisen from an abortion: Provided, That nothing herein shall preclude an employer from providing abortion benefits or otherwise affect bargaining agreements in regard to abortion."],[1,"(l) The term \"complaining party\" means the Commission, the Attorney General, or a person who may bring an action or proceeding under this subchapter."],[1,"(m) The term \"demonstrates\" means meets the burdens of production and persuasion."],[1,"(n) The term \"respondent\" means an employer, employment agency, labor organization, joint labor-management committee controlling apprenticeship or other training or retraining program, including an on-the-job training program, or Federal entity subject to section 2000e–16 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e?type=usc&year=mostrecent&link-type=html"},"op":11,"head":"§2000e. Definitions","tname":"The Public Health and Welfare","by":{"1":"3, 9, 13, 15, 17"}},{"t":"usc","label":"42 U.S.C. § 2000e-2","url":"https://www.law.cornell.edu/uscode/text/42/2000e-2","subs":["(a)","(a)(1)"],"by":{"1":"19, 15"}},{"t":"usc","label":"42 U.S.C. § 2000e-5","url":"https://www.law.cornell.edu/uscode/text/42/2000e-5","subs":["(b)","(c)","(e)","(e)(1)","(e)(3)(A)","(g)(1)","(f)(1)"],"stext":{"head":"§2000e–5. Enforcement provisions","paras":[[0,"(a) Power of Commission to prevent unlawful employment practices"],[0,"The Commission is empowered, as hereinafter provided, to prevent any person from engaging in any unlawful employment practice as set forth in section 2000e–2 or 2000e–3 of this title."],[0,"(b) Charges by persons aggrieved or member of Commission of unlawful employment practices by employers, etc.; filing; allegations; notice to respondent; contents of notice; investigation by Commission; contents of charges; prohibition on disclosure of charges; determination of reasonable cause; conference, conciliation, and persuasion for elimination of unlawful practices; prohibition on disclosure of informal endeavors to end unlawful practices; use of evidence in subsequent proceedings; penalties for disclosure of information; time for determination of reasonable cause"],[0,"Whenever a charge is filed by or on behalf of a person claiming to be aggrieved, or by a member of the Commission, alleging that an employer, employment agency, labor organization, or joint labor-management committee controlling apprenticeship or other training or retraining, including on-the-job training programs, has engaged in an unlawful employment practice, the Commission shall serve a notice of the charge (including the date, place and circumstances of the alleged unlawful employment practice) on such employer, employment agency, labor organization, or joint labor-management committee (hereinafter referred to as the \"respondent\") within ten days, and shall make an investigation thereof. Charges shall be in writing under oath or affirmation and shall contain such information and be in such form as the Commission requires. Charges shall not be made public by the Commission. If the Commission determines after such investigation that there is not reasonable cause to believe that the charge is true, it shall dismiss the charge and promptly notify the person claiming to be aggrieved and the respondent of its action. In determining whether reasonable cause exists, the Commission shall accord substantial weight to final findings and orders made by State or local authorities in proceedings commenced under State or local law pursuant to the requirements of subsections (c) and (d). If the Commission determines after such investigation that there is reasonable cause to believe that the charge is true, the Commission shall endeavor to eliminate any such alleged unlawful employment practice by informal methods of conference, conciliation, and persuasion. Nothing said or done during and as a part of such informal endeavors may be made public by the Commission, its officers or employees, or used as evidence in a subsequent proceeding without the written consent of the persons concerned. Any person who makes public information in violation of this subsection shall be fined not more than $1,000 or imprisoned for not more than one year, or both. The Commission shall make its determination on reasonable cause as promptly as possible and, so far as practicable, not later than one hundred and twenty days from the filing of the charge or, where applicable under subsection (c) or (d), from the date upon which the Commission is authorized to take action with respect to the charge."],[0,"(c) State or local enforcement proceedings; notification of State or local authority; time for filing charges with Commission; commencement of proceedings"],[0,"In the case of an alleged unlawful employment practice occurring in a State, or political subdivision of a State, which has a State or local law prohibiting the unlawful employment practice alleged and establishing or authorizing a State or local authority to grant or seek relief from such practice or to institute criminal proceedings with respect thereto upon receiving notice thereof, no charge may be filed under subsection (a) 1 by the person aggrieved before the expiration of sixty days after proceedings have been commenced under the State or local law, unless such proceedings have been earlier terminated, provided that such sixty-day period shall be extended to one hundred and twenty days during the first year after the effective date of such State or local law. If any requirement for the commencement of such proceedings is imposed by a State or local authority other than a requirement of the filing of a written and signed statement of the facts upon which the proceeding is based, the proceeding shall be deemed to have been commenced for the purposes of this subsection at the time such statement is sent by registered mail to the appropriate State or local authority."],[0,"(d) State or local enforcement proceedings; notification of State or local authority; time for action on charges by Commission"],[0,"In the case of any charge filed by a member of the Commission alleging an unlawful employment practice occurring in a State or political subdivision of a State which has a State or local law prohibiting the practice alleged and establishing or authorizing a State or local authority to grant or seek relief from such practice or to institute criminal proceedings with respect thereto upon receiving notice thereof, the Commission shall, before taking any action with respect to such charge, notify the appropriate State or local officials and, upon request, afford them a reasonable time, but not less than sixty days (provided that such sixty-day period shall be extended to one hundred and twenty days during the first year after the effective day of such State or local law), unless a shorter period is requested, to act under such State or local law to remedy the practice alleged."],[0,"(e) Time for filing charges; time for service of notice of charge on respondent; filing of charge by Commission with State or local agency; seniority system"],[0,"(1) A charge under this section shall be filed within one hundred and eighty days after the alleged unlawful employment practice occurred and notice of the charge (including the date, place and circumstances of the alleged unlawful employment practice) shall be served upon the person against whom such charge is made within ten days thereafter, except that in a case of an unlawful employment practice with respect to which the person aggrieved has initially instituted proceedings with a State or local agency with authority to grant or seek relief from such practice or to institute criminal proceedings with respect thereto upon receiving notice thereof, such charge shall be filed by or on behalf of the person aggrieved within three hundred days after the alleged unlawful employment practice occurred, or within thirty days after receiving notice that the State or local agency has terminated the proceedings under the State or local law, whichever is earlier, and a copy of such charge shall be filed by the Commission with the State or local agency."],[0,"(2) For purposes of this section, an unlawful employment practice occurs, with respect to a seniority system that has been adopted for an intentionally discriminatory purpose in violation of this subchapter (whether or not that discriminatory purpose is apparent on the face of the seniority provision), when the seniority system is adopted, when an individual becomes subject to the seniority system, or when a person aggrieved is injured by the application of the seniority system or provision of the system."],[0,"(3)(A) For purposes of this section, an unlawful employment practice occurs, with respect to discrimination in compensation in violation of this subchapter, when a discriminatory compensation decision or other practice is adopted, when an individual becomes subject to a discriminatory compensation decision or other practice, or when an individual is affected by application of a discriminatory compensation decision or other practice, including each time wages, benefits, or other compensation is paid, resulting in whole or in part from such a decision or other practice."],[0,"(B) In addition to any relief authorized by section 1981a of this title, liability may accrue and an aggrieved person may obtain relief as provided in subsection (g)(1), including recovery of back pay for up to two years preceding the filing of the charge, where the unlawful employment practices that have occurred during the charge filing period are similar or related to unlawful employment practices with regard to discrimination in compensation that occurred outside the time for filing a charge."],[0,"(f) Civil action by Commission, Attorney General, or person aggrieved; preconditions; procedure; appointment of attorney; payment of fees, costs, or security; intervention; stay of Federal proceedings; action for appropriate temporary or preliminary relief pending final disposition of charge; jurisdiction and venue of United States courts; designation of judge to hear and determine case; assignment of case for hearing; expedition of case; appointment of master"],[0,"(1) If within thirty days after a charge is filed with the Commission or within thirty days after expiration of any period of reference under subsection (c) or (d), the Commission has been unable to secure from the respondent a conciliation agreement acceptable to the Commission, the Commission may bring a civil action against any respondent not a government, governmental agency, or political subdivision named in the charge. In the case of a respondent which is a government, governmental agency, or political subdivision, if the Commission has been unable to secure from the respondent a conciliation agreement acceptable to the Commission, the Commission shall take no further action and shall refer the case to the Attorney General who may bring a civil action against such respondent in the appropriate United States district court. The person or persons aggrieved shall have the right to intervene in a civil action brought by the Commission or the Attorney General in a case involving a government, governmental agency, or political subdivision. If a charge filed with the Commission pursuant to subsection (b), is dismissed by the Commission, or if within one hundred and eighty days from the filing of such charge or the expiration of any period of reference under subsection (c) or (d), whichever is later, the Commission has not filed a civil action under this section or the Attorney General has not filed a civil action in a case involving a government, governmental agency, or political subdivision, or the Commission has not entered into a conciliation agreement to which the person aggrieved is a party, the Commission, or the Attorney General in a case involving a government, governmental agency, or political subdivision, shall so notify the person aggrieved and within ninety days after the giving of such notice a civil action may be brought against the respondent named in the charge (A) by the person claiming to be aggrieved or (B) if such charge was filed by a member of the Commission, by any person whom the charge alleges was aggrieved by the alleged unlawful employment practice. Upon application by the complainant and in such circumstances as the court may deem just, the court may appoint an attorney for such complainant and may authorize the commencement of the action without the payment of fees, costs, or security. Upon timely application, the court may, in its discretion, permit the Commission, or the Attorney General in a case involving a government, governmental agency, or political subdivision, to intervene in such civil action upon certification that the case is of general public importance. Upon request, the court may, in its discretion, stay further proceedings for not more than sixty days pending the termination of State or local proceedings described in subsection (c) or (d) of this section or further efforts of the Commission to obtain voluntary compliance."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e-5?type=usc&year=mostrecent&link-type=html"},"head":"§2000e–5. Enforcement provisions","tname":"The Public Health and Welfare","by":{"1":"4, 4, 4, 4, 4, 4, 4, 4, 4","2":"18, 24"}},{"t":"reg","label":"29 C.F.R. § 1601.28","url":"https://www.ecfr.gov/current/title-29/section-1601.28","subs":["(a)(1)"],"by":{"1":"4"}},{"t":"case","label":"Akridge v. Alfa Ins. Companies","cite":"93 F.4th 1181","y":2024,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/93/1181/","by":{"2":"20","3":"5"}},{"t":"case","label":"Aldana v. Del Monte Fresh Produce, N.A., Inc.","cite":"416 F.3d 1242","y":2005,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/416/1242/","by":{"2":"22"}},{"t":"case","label":"Alexander v. Choate","cite":"469 U.S. 287","y":1985,"id":"1984/83-727","sc":1,"sum":"Assuming that § 504 or its implementing regulations reach some claims of disparate-impact discrimination, the effect of Tennessee's reduction in annual inpatient hospital coverage is not among them.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"5"}},{"t":"case","label":"Almond v. Unified Sch. Dist. No. 501","cite":"665 F.3d 1174","y":2011,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/665/1174/","by":{"2":"11, 26"}},{"t":"case","label":"Associated Gen. Contractors of California, Inc. v. California State Council of Carpenters","cite":"459 U.S. 519","y":1983,"id":"1982/81-334","sc":1,"sum":"Based on the allegations of the complaint, the Union was not a person injured by reason of a violation of the antitrust laws within the meaning of § 4 of the Clayton Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"AT & T Corp. v. Hulteen","cite":"556 U.S. 701","y":2009,"id":"2008/07-543","sc":1,"sum":"The Court held that a company does not violate the Pregnancy Discrimination Act (PDA) or Title VII when it denies retirement benefits to women who took a temporary disability leave while pregnant when the leave was taken before the PDA came into effect.","sumSrc":"Oyez","by":{"2":"25"}},{"t":"case","label":"Barnhart v. Sigmon Coal Co.","cite":"534 U.S. 438","y":2002,"id":"2001/00-1307","sc":1,"sum":"The Court held that the Act did not permit the Commissioner to assign retired miners to the successors in interest of out-of-business signatory operators, since the companies were not related to such operators under the Act's statutory definitions.","sumSrc":"Oyez","by":{"2":"37, 49"}},{"t":"case","label":"Bass v. City of Orlando","cite":"57 F. Supp. 2d 1318","y":1999,"court":"M.D. Fla.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/57/1318/","by":{"2":"22"}},{"t":"case","label":"Bostock v. Clayton Cnty., Georgia","cite":"590 U.S. 644","y":2020,"id":"2019/17-1618","sc":1,"sum":"The Court held that Title VII of the Civil Rights Act of 1964, which prohibits against employment discrimination “because of . . . sex” encompasses discrimination based on an individual’s sexual orientation.","sumSrc":"Oyez","by":{"2":"19, 33, 39","3":"8"}},{"t":"case","label":"Citizens United v. Fed. Election Comm'n","cite":"558 U.S. 310","y":2010,"id":"2008/08-205","sc":1,"op":3,"sum":"Holding that parties can make any Jackson, J., dissenting argument in this Court to support their claim, even one not raised below.","sumSrc":"opinion","by":{"2":"17"}},{"t":"case","label":"City of Austin, Texas v. Reagan Nat'l Advert. of Austin, LLC","cite":"596 U.S. 61","y":2022,"id":"2021/20-1029","sc":1,"sum":"The distinction between on-premises signs and off-premises signs in the City of Austin’s sign code is facially content neutral under the First Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"1, 21"}},{"t":"case","label":"\u0003 vi \u0003 City of Hollywood v. Bien","cite":"209 So. 3d 1","y":2016,"court":"Fla. Dist. Ct. App.","url":"https://www.courtlistener.com/c/So.%203d/209/1/","by":{"2":"6, 51"}},{"t":"case","label":"City of Springfield, Mass. v. Kibbe","cite":"480 U.S. 257","y":1987,"id":"1986/85-1217","sc":1,"sum":"The writ of certiorari is dismissed as improvidently granted. Although petitioner argues here that a heightened negligence standard does not suffice under Monell's requirement of a municipal policy, this Court ordinarily will not decide questions not raised or litigated in the lower courts, especially where the party seeking to argue the issue has failed to object to a jury instruction, as required by Rule 51 of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"18"}},{"t":"case","label":"Cleveland v. Policy Mgmt. Sys. Corp.","cite":"526 U.S. 795","y":1999,"id":"1998/97-1008","sc":1,"op":5,"sum":"The Court held that SSDI and ADA claims do not conflict in such a way as to automatically bar anyone from raising them jointly. The Court explained that when determining SSDI eligibility, the significant ADA question of whether someone would have been capable of performing their job if \"reasonable accommodations\" had been made by their employer, is not considered.","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"Clifford F. MacEvoy Co. v. U.S. for Use & Benefit of Calvin Tomkins Co.","cite":"322 U.S. 102","y":1944,"id":"scdb/1943-048","sc":1,"sum":"1. Where A sold materials to B who merely sold them to a contractor for use on a Government project, A is not entitled to recover upon a payment bond furnished by the contractor pursuant to the Miller Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"48"}},{"t":"case","label":"Davis v. Bombardier Transp. Holdings (USA) Inc.","cite":"794 F.3d 266","y":2015,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/794/266/","by":{"2":"24, 25"}},{"t":"case","label":"Delaware State Coll. v. Ricks","cite":"449 U.S. 250","y":1980,"id":"1980/79-939","sc":1,"sum":"Respondent's Title VII and § 1981 claims were untimely.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"16, 26"}},{"t":"case","label":"Dunlap v. Liberty Nat. Prod., Inc.","cite":"878 F.3d 794","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/878/794/","by":{"2":"11"}},{"t":"case","label":"Florida Sheriffs Ass'n v. Dep't of Admin., Div. of Ret.","cite":"408 So. 2d 1033","y":1981,"court":"Fla.","url":"https://www.courtlistener.com/c/So.%202d/408/1033/","by":{"2":"8"}},{"t":"case","label":"Ford v. Schering-Plough Corp.","cite":"145 F.3d 601","y":1998,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/145/601/","ar":1,"by":{"2":"27, 37, 49"}},{"t":"case","label":"Honeycutt v. United States","cite":"581 U.S. 443","y":2017,"id":"2016/16-142","sc":1,"sum":"The Court determined that the federal forfeiture statute does not require joint and several liability among co-conspirators for any reasonably foreseeable proceeds of conspiracy.","sumSrc":"Oyez","by":{"2":"48"}},{"t":"case","label":"Irvine v. People of California","cite":"347 U.S. 128","y":1954,"id":"1940-1955/347us128","sc":1,"sum":"The Court upheld Irvine's conviction though without commanding a majority as to the Court's reasoning.","sumSrc":"Oyez","by":{"2":"14"}},{"t":"case","label":"\u0003 vii \u0003 Lohrasbi v. Bd. of Trustees of the Univ. of Illinois","cite":"147 F. Supp. 3d 746","y":2015,"court":"C.D. Ill.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/147/746/","by":{"2":"26"}},{"t":"case","label":"Marx v. General Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"op":2,"sum":"The Court held that the Federal Rules of Civil Procedure awards costs to the prevailing party unless a statute explicitly states otherwise.","sumSrc":"Oyez","by":{"2":"44"}},{"t":"case","label":"McKnight v. Gen. Motors Corp.","cite":"550 F.3d 519","y":2008,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/550/519/","ar":1,"by":{"2":"27, 34"}},{"t":"case","label":"McReynolds v. Merrill Lynch & Co., Inc.","cite":"694 F.3d 873","y":2012,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/694/873/","by":{"2":"25"}},{"t":"case","label":"Morgan v. Joint Admin. Bd.","cite":"268 F.3d 456","y":2001,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/268/456/","op":1,"by":{"2":"27, 33, 37"}},{"t":"case","label":"Murray v. Warren Pumps, LLC","cite":"821 F.3d 77","y":2016,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/821/77/","by":{"2":"19"}},{"t":"case","label":"Smith v. Town of Ramapo","cite":"745 Fed. Appx. 424","y":2018,"court":"2d Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./745/424/","by":{"2":"37, 40"}},{"t":"case","label":"Stevens v. Rite Aid Corp.","cite":"851 F.3d 224","y":2017,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/851/224/","by":{"2":"50"}},{"t":"case","label":"Sutton v. United Air Lines, Inc.","cite":"527 U.S. 471","y":1999,"id":"1998/97-1943","sc":1,"sum":"This reading is in harmony with the statutory language and history of the ADA because (1) the phrase \"substantially limits\" requires consideration of present, not future or hypothetical, impairment; (2) the ADA calls for individualized assessments of impairment; and (3) Congress found that approximately 43 million Americans were disabled, a number that would be far too low if Congress had meant to include all those with correctable impairments.","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"Taylor v. Food World, Inc.","cite":"133 F.3d 1419","y":1998,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/133/1419/","by":{"2":"13"}},{"t":"case","label":"Taylor v. Michael","cite":"724 F.3d 806","court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/724/806/","op":2,"by":{"2":"25"}},{"t":"case","label":"Tennessee v. Lane","cite":"541 U.S. 509","y":2004,"id":"2003/02-1667","sc":1,"sum":"In a 5-to-4 opinion written by Justice John Paul Stevens, the Court held that Congress had sufficiently demonstrated the problems faced by disabled persons who sought to exercise fundamental rights protected by the Due Process clause of the 14th Amendment (such as access to a court).","sumSrc":"Oyez","by":{"2":"3, 50"}},{"t":"case","label":"\u0003 viii \u0003 Tyndall v. Nat'l Educ. Centers, Inc. of California","cite":"31 F.3d 209","y":1994,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/31/209/","by":{"2":"33"}},{"t":"case","label":"United States v. Dicter","cite":"198 F.3d 1284","y":1999,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/198/1284/","by":{"2":"18"}},{"t":"case","label":"United States v. Wilson","cite":"503 U.S. 329","y":1992,"id":"1991/90-1745","sc":1,"op":1,"sum":"It is the Attorney General who computes the amount of the § 3585(b) credit after the defendant has begun to serve his sentence.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"29"}},{"t":"case","label":"Wagner v. Daewoo Heavy Indus. Am. Corp.","cite":"314 F.3d 541","y":2002,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/314/541/","by":{"2":"23"}},{"t":"case","label":"Walters v. Metro. Educational Enters.","cite":"519 U.S. 202","y":1997,"id":"1996/95-259","sc":1,"op":2,"sum":"Authored by Justice Antonin Scalia, the Court ruled that the ultimate touchstone under Title VII of the Civil Rights Act of 1964 is whether an employer has employment relationships with 15 or more individuals for each working day in 20 or more weeks during the year in question.","sumSrc":"Oyez","by":{"2":"31, 32"}},{"t":"case","label":"Weyer v. Twentieth Century Fox Film Corp.","cite":"198 F.3d 1104","y":2000,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/198/1104/","op":1,"ar":1,"by":{"2":"13, 19, 27, 32, 34, 49-51"}},{"t":"case","label":"Williams v. United Ins. Co. of Am.","cite":"253 F.3d 280","y":2001,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/253/280/","by":{"2":"3"}},{"t":"case","label":"Williams-Yulee v. Florida Bar","cite":"575 U.S. 433","y":2015,"id":"2014/13-1499","sc":1,"sum":"The Court held that a rule prohibiting judicial candidates from personally soliciting campaign funds does not violate the First Amendment.","sumSrc":"Oyez","by":{"2":"46"}},{"t":"usc","label":"1 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/1/1","by":{"2":"29"}},{"t":"usc","label":"42 U.S.C. § 426","url":"https://www.law.cornell.edu/uscode/text/42/426","subs":["(b)(2)(A)"],"stext":{"head":"§426. Entitlement to hospital insurance benefits","paras":[[0,"(a) Individuals over 65 years"],[0,"Every individual who—"],[1,"(1) has attained age 65, and"],[1,"(2)(A) is entitled to monthly insurance benefits under section 402 of this title, would be entitled to those benefits except that he has not filed an application therefor (or application has not been made for a benefit the entitlement to which for any individual is a condition of entitlement therefor), or would be entitled to such benefits but for the failure of another individual, who meets all the criteria of entitlement to monthly insurance benefits, to meet such criteria throughout a month, and, in conformity with regulations of the Secretary, files an application for hospital insurance benefits under part A of subchapter XVIII,"],[1,"(B) is a qualified railroad retirement beneficiary, or"],[1,"(C)(i) would meet the requirements of subparagraph (A) upon filing application for the monthly insurance benefits involved if medicare qualified government employment (as defined in section 410(p) of this title) were treated as employment (as defined in section 410(a) of this title) for purposes of this subchapter, and (ii) files an application, in conformity with regulations of the Secretary, for hospital insurance benefits under part A of subchapter XVIII,"],[0,"shall be entitled to hospital insurance benefits under part A of subchapter XVIII for each month for which he meets the condition specified in paragraph (2), beginning with the first month after June 1966 for which he meets the conditions specified in paragraphs (1) and (2)."],[0,"(b) Individuals under 65 years"],[0,"Every individual who—"],[1,"(1) has not attained age 65, and"],[1,"(2)(A) is entitled to, and has for 24 calendar months been entitled to, (i) disability insurance benefits under section 423 of this title or (ii) child's insurance benefits under section 402(d) of this title by reason of a disability (as defined in section 423(d) of this title) or (iii) widow's insurance benefits under section 402(e) of this title or widower's insurance benefits under section 402(f) of this title by reason of a disability (as defined in section 423(d) of this title), or"],[1,"(B) is, and has been for not less than 24 months, a disabled qualified railroad retirement beneficiary, within the meaning of section 231f(d) of title 45, or"],[1,"(C)(i) has filed an application, in conformity with regulations of the Secretary, for hospital insurance benefits under part A of subchapter XVIII pursuant to this subparagraph, and"],[1,"(ii) would meet the requirements of subparagraph (A) (as determined under the disability criteria, including reviews, applied under this subchapter), including the requirement that he has been entitled to the specified benefits for 24 months, if—"],[2,"(I) medicare qualified government employment (as defined in section 410(p) of this title) were treated as employment (as defined in section 410(a) of this title) for purposes of this subchapter, and"],[2,"(II) the filing of the application under clause (i) of this subparagraph were deemed to be the filing of an application for the disability-related benefits referred to in clause (i), (ii), or (iii) of subparagraph (A),"],[0,"shall be entitled to hospital insurance benefits under part A of subchapter XVIII for each month beginning with the later of (I) July 1973 or (II) the twenty-fifth month of his entitlement or status as a qualified railroad retirement beneficiary described in paragraph (2), and ending (subject to the last sentence of this subsection) with the month following the month in which notice of termination of such entitlement to benefits or status as a qualified railroad retirement beneficiary described in paragraph (2) is mailed to him, or if earlier, with the month before the month in which he attains age 65. In applying the previous sentence in the case of an individual described in paragraph (2)(C), the \"twenty-fifth month of his entitlement\" refers to the first month after the twenty-fourth month of entitlement to specified benefits referred to in paragraph (2)(C) and \"notice of termination of such entitlement\" refers to a notice that the individual would no longer be determined to be entitled to such specified benefits under the conditions described in that paragraph. For purposes of this subsection, an individual who has had a period of trial work which ended as provided in section 422(c)(4)(A) of this title, and whose entitlement to benefits or status as a qualified railroad retirement beneficiary as described in paragraph (2) has subsequently terminated, shall be deemed to be entitled to such benefits or to occupy such status (notwithstanding the termination of such entitlement or status) for the period of consecutive months throughout all of which the physical or mental impairment, on which such entitlement or status was based, continues, and throughout all of which such individual would have been entitled to monthly insurance benefits under this subchapter or as a qualified railroad retirement beneficiary had such individual been unable to engage in substantial gainful activity, but not in excess of 78 such months. In determining when an individual's entitlement or status terminates for purposes of the preceding sentence, the term \"36 months\" in the second sentence of section 423(a)(1) of this title, in section 402(d)(1)(G)(i) of this title, in the last sentence of section 402(e)(1) of this title, and in the last sentence of section 402(f)(1) of this title shall be applied as though it read \"15 months\"."],[0,"(c) Conditions"],[0,"For purposes of subsection (a)—"],[1,"(1) entitlement of an individual to hospital insurance benefits for a month shall consist of entitlement to have payment made under, and subject to the limitations in, part A of subchapter XVIII on his behalf for inpatient hospital services, post-hospital extended care services, and home health services (as such terms are defined in part E of subchapter XVIII) furnished him in the United States (or outside the United States in the case of inpatient hospital services furnished under the conditions described in section 1395f(f) of this title) during such month; except that (A) no such payment may be made for post-hospital extended care services furnished before January 1967, and (B) no such payment may be made for post-hospital extended care services unless the discharge from the hospital required to qualify such services for payment under part A of subchapter XVIII occurred (i) after June 30, 1966, or on or after the first day of the month in which he attains age 65, whichever is later, or (ii) if he was entitled to hospital insurance benefits pursuant to subsection (b), at a time when he was so entitled; and"],[1,"(2) an individual shall be deemed entitled to monthly insurance benefits under section 402 or section 423 of this title, or to be a qualified railroad retirement beneficiary, for the month in which he died if he would have been entitled to such benefits, or would have been a qualified railroad retirement beneficiary, for such month had he died in the next month."],[0,"(d) \"Qualified railroad retirement beneficiary\" defined"],[0,"For purposes of this section, the term \"qualified railroad retirement beneficiary\" means an individual whose name has been certified to the Secretary by the Railroad Retirement Board under section 231f(d) of title 45. An individual shall cease to be a qualified railroad retirement beneficiary at the close of the month preceding the month which is certified by the Railroad Retirement Board as the month in which he ceased to meet the requirements of section 231f(d) of title 45."],[0,"(e) Benefits for widows and widowers"],[0,"(1)(A) For purposes of determining entitlement to hospital insurance benefits under subsection (b) in the case of widows and widowers described in paragraph (2)(A)(iii) thereof—"],[1,"(i) the term \"age 60\" in sections 402(e)(1)(B)(ii), 402(e)(4), 402(f)(1)(B)(ii), and 402(f)(4) of this title shall be deemed to read \"age 65\"; and"],[1,"(ii) the phrase \"before she attained age 60\" in the matter following subparagraph (F) of section 402(e)(1) of this title and the phrase \"before he attained age 60\" in the matter following subparagraph (F) of section 402(f)(1) of this title shall each be deemed to read \"based on a disability\"."],[0,"(B) For purposes of subsection (b)(2)(A)(iii), each month in the period commencing with the first month for which an individual is first eligible for supplemental security income benefits under subchapter XVI, or State supplementary payments of the type referred to in section 1382e(a) of this title (or payments of the type described in section 212(a) of Public Law 93–66) which are paid by the Secretary under an agreement referred to in section 1382e(a) of this title (or in section 212(b) of Public Law 93–66), shall be included as one of the 24 months for which such individual must have been entitled to widow's or widower's insurance benefits on the basis of disability in order to become entitled to hospital insurance benefits on that basis."],[0,"(2) For purposes of determining entitlement to hospital insurance benefits under subsection (b) in the case of an individual under age 65 who is entitled to benefits under section 402 of this title, and who was entitled to widow's insurance benefits or widower's insurance benefits based on disability for the month before the first month in which such individual was so entitled to old-age insurance benefits (but ceased to be entitled to such widow's or widower's insurance benefits upon becoming entitled to such old-age insurance benefits), such individual shall be deemed to have continued to be entitled to such widow's insurance benefits or widower's insurance benefits for and after such first month."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/426?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§426. Entitlement to hospital insurance benefits","tname":"The Public Health and Welfare","by":{"2":"7"}},{"t":"usc","label":"42 U.S.C. § 1395o","url":"https://www.law.cornell.edu/uscode/text/42/1395o","subs":["(a)(1)"],"by":{"2":"7"}},{"t":"usc","label":"42 U.S.C. § 12203","url":"https://www.law.cornell.edu/uscode/text/42/12203","subs":["(a)"],"stext":{"head":"§12203. Prohibition against retaliation and coercion","paras":[[0,"(a) Retaliation"],[0,"No person shall discriminate against any individual because such individual has opposed any act or practice made unlawful by this chapter or because such individual made a charge, testified, assisted, or participated in any manner in an investigation, proceeding, or hearing under this chapter."],[0,"(b) Interference, coercion, or intimidation"],[0,"It shall be unlawful to coerce, intimidate, threaten, or interfere with any individual in the exercise or enjoyment of, or on account of his or her having exercised or enjoyed, or on account of his or her having aided or encouraged any other individual in the exercise or enjoyment of, any right granted or protected by this chapter."],[0,"(c) Remedies and procedures"],[0,"The remedies and procedures available under sections 12117, 12133, and 12188 of this title shall be available to aggrieved persons for violations of subsections (a) and (b), with respect to subchapter I, subchapter II and subchapter III, respectively."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/12203?type=usc&year=mostrecent&link-type=html"},"head":"§12203. Prohibition against retaliation and coercion","tname":"The Public Health and Welfare","by":{"2":"37","3":"14, 15"}},{"t":"case","label":"14 Penn Plaza LLC v. Pyett","cite":"556 U.S. 247","y":2009,"id":"2008/07-581","sc":1,"sum":"The Court held that arbitration clauses in employment contracts are enforceable as a matter of federal law.","sumSrc":"Oyez","by":{"3":"19"}},{"t":"case","label":"Alexander v. Gardner-Denver Co.","cite":"415 U.S. 36","y":1974,"id":"1973/72-5847","sc":1,"sum":"An employee's statutory right to trial de novo under Title VII of the Civil Rights Act of 1964 is not foreclosed by prior submission of his claim to final arbitration under the nondiscrimination clause of a collective-bargaining.agreement.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"16"}},{"t":"case","label":"Bittner v. United States","cite":"598 U.S. 85","y":2023,"id":"2022/21-1195","sc":1,"sum":"The Bank Secrecy Act’s $10,000 maximum penalty for the nonwillful failure to file a compliant report accrues on a per-report, not a per-account, basis.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"8"}},{"t":"case","label":"City of Cleburne v. Cleburne Living Center","cite":"473 U.S. 432","y":1985,"id":"1984/84-468","sc":1,"sum":"In a unanimous judgment, the Court held that the denial of the special use permit to Cleburne Living Centers, Inc. was premised on an irrational prejudice against the mentally retarded, and hence unconstitutional under the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"3":"16"}},{"t":"case","label":"Fischer v. United States","cite":"603 U.S. 480","y":2024,"id":"2023/23-5572","sc":1,"sum":"The Court held that 18 U.S.C. § 1512(c), which prohibits obstruction of congressional inquiries and investigations, does not include acts unrelated to investigations and evidence.","sumSrc":"Oyez","by":{"3":"14"}},{"t":"case","label":"Mertens v. Hewitt Associates","cite":"508 U.S. 248","y":1993,"id":"1992/91-1671","sc":1,"sum":"ERISA does not authorize suits for money damages against nonfiduciaries who knowingly participate in a fiduciary's breach of fiduciary duty. ERISA §502(a)(3) permits plan participants to bring civil actions to obtain \"appropriate equitable relief\" to redress violations of the statute or a plan. Assuming, arguendo,that this creates a cause of action against nonfiduciaries who knowingly assist in a fiduciary's breach …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"16"}},{"t":"case","label":"Natofsky v. City of New York","cite":"921 F.3d 337","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/921/337/","by":{"3":"5"}},{"t":"case","label":"Niz-Chavez v. Garland","cite":"593 U.S. 155","y":2021,"id":"2020/19-863","sc":1,"sum":"A notice to appear sufficient to trigger the Illegal Immigration Reform and Immigrant Responsibility Act of 1996’s stop-time rule is a single document containing all the information about an individual’s removal hearing specified in 8 U. S. C. §1229(a)(1).","sumSrc":"Holding (supremecourt.gov)","by":{"3":"11"}},{"t":"case","label":"North Haven Board of Education v. Bell","cite":"456 U.S. 512","y":1982,"id":"1981/80-986","sc":1,"sum":"The Court held that, while Title IX does not expressly include employees, Congress’s choice of words, i.e. “no person” as opposed to “student” or “beneficiary”, implies an intention to broadly cover individuals involved in educational institutions rather than only students.","sumSrc":"Oyez","by":{"3":"16"}},{"t":"case","label":"Richlin Security Service Co. v. Chertoff","cite":"553 U.S. 571","y":2008,"id":"2007/06-1717","sc":1,"sum":"The Court held that such paralegal fees are recoverable at market rates. Justice Samuel A. Alito stated that because Richlin incurred fees for paralegal services in connection with its case, a straightforward reading of the statute demonstrates that Richlin was entitled to recover fees for the paralegal services it purchased at the market rate.","sumSrc":"Oyez","by":{"3":"20"}},{"t":"case","label":"Ross v. Blake","cite":"578 U.S. 632","y":2016,"id":"2015/15-339","sc":1,"sum":"The Court determined that the Prison Litigation Reform Act’s requirement to exhaust administrative remedies does not have a “special circumstances” exception.","sumSrc":"Oyez","by":{"3":"5"}},{"t":"case","label":"Smith v. Arizona","cite":"602 U.S. 779","y":2024,"id":"2023/22-899","sc":1,"sum":"When an expert conveys an absent lab analyst’s statements in support of the expert’s opinion, and the statements provide that support only if true, then the statements come into evidence for their truth, and thus implicate the Sixth Amendment’s Confrontation Clause.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"20"}},{"t":"case","label":"Stolt-Nielsen S.A. v. AnimalFeeds International Corp.","cite":"559 U.S. 662","y":2010,"id":"2009/08-1198","sc":1,"op":1,"sum":"The Court held that imposing class arbitration on parties who have not agreed to authorize class arbitration is inconsistent with the Federal Arbitration Act.","sumSrc":"Oyez","by":{"3":"18"}},{"t":"case","label":"United Savings Association of Texas v. Timbers of Inwood Forest Associates, Ltd.","cite":"484 U.S. 365","y":1988,"id":"1987/86-1602","sc":1,"sum":"Undersecured creditors are not entitled to compensation under § 362(d)(1) for the delay caused by the automatic stay in foreclosing on their collateral.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"15"}},{"t":"case","label":"United States v. Eshetu","cite":"898 F.3d 36","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/898/36/","by":{"3":"18"}},{"t":"law","label":"Pub. L. No. 104-191","url":"https://www.govinfo.gov/link/plaw/104/public/191","by":{"3":"16"}},{"t":"law","label":"Pub. L. No. 101-336","url":"https://www.govinfo.gov/link/statute/104/327","by":{"3":"5"}},{"t":"usc","label":"29 U.S.C. § 1002","url":"https://www.law.cornell.edu/uscode/text/29/1002","by":{"3":"16"}},{"t":"usc","label":"29 U.S.C. § 1003","url":"https://www.law.cornell.edu/uscode/text/29/1003","by":{"3":"16"}},{"t":"usc","label":"29 U.S.C. § 1132","url":"https://www.law.cornell.edu/uscode/text/29/1132","by":{"3":"16"}},{"t":"usc","label":"29 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/29/1182","by":{"3":"16"}},{"t":"usc","label":"42 U.S.C. § 1981","url":"https://www.law.cornell.edu/uscode/text/42/1981","by":{"3":"16"}},{"t":"usc","label":"42 U.S.C. § 2000","url":"https://www.law.cornell.edu/uscode/text/42/2000","by":{"3":"6, 7"}},{"t":"usc","label":"42 U.S.C. § 12182","url":"https://www.law.cornell.edu/uscode/text/42/12182","by":{"3":"15"}},{"t":"usc","label":"42 U.S.C. § 12201","url":"https://www.law.cornell.edu/uscode/text/42/12201","by":{"3":"13, 14"}},{"t":"usc","label":"51 U.S.C. § 30902","url":"https://www.law.cornell.edu/uscode/text/51/30902","stext":{"head":"§30902. Charles \"Pete\" Conrad Astronomy Awards","paras":[[0,"(a) Short Title.—This section may be cited as the \"Charles 'Pete' Conrad Astronomy Awards Act\"."],[0,"(b) Definitions.—In this section:"],[1,"(1) Amateur astronomer.—The term \"amateur astronomer\" means an individual whose employer does not provide any funding, payment, or compensation to the individual for the observation of asteroids and other celestial bodies, and does not include any individual employed as a professional astronomer."],[1,"(2) Minor planet center.—The term \"Minor Planet Center\" means the Minor Planet Center of the Smithsonian Astrophysical Observatory."],[1,"(3) Near-earth asteroid.—The term \"near-Earth asteroid\" means an asteroid with a perihelion distance of less than 1.3 Astronomical Units from the Sun."],[1,"(4) Program.—The term \"Program\" means the Charles \"Pete\" Conrad Astronomy Awards Program established under subsection (c)."],[0,"(c) Charles \"Pete\" Conrad Astronomy Awards Program.—"],[1,"(1) In general.—The Administrator shall establish the Charles \"Pete\" Conrad Astronomy Awards Program."],[1,"(2) Awards.—The Administrator shall make awards under the Program based on the recommendations of the Minor Planet Center."],[1,"(3) Award categories.—The Administrator shall make one annual award, unless there are no eligible discoveries or contributions, for each of the following categories:"],[2,"(A) Discovery of brightest near-earth asteroid.—The amateur astronomer or group of amateur astronomers who in the preceding calendar year discovered the intrinsically brightest near-Earth asteroid among the near-Earth asteroids that were discovered during that year by amateur astronomers or groups of amateur astronomers."],[2,"(B) Greatest contribution to cataloguing near-earth asteroids.—The amateur astronomer or group of amateur astronomers who made the greatest contribution to the Minor Planet Center's mission of cataloguing near-Earth asteroids during the preceding year."],[1,"(4) Award amount.—An award under the Program shall be in the amount of $3,000."],[1,"(5) Guidelines.—"],[2,"(A) Citizen or permanent resident.—No individual who is not a citizen or permanent resident of the United States at the time of the individual's discovery or contribution may receive an award under this section."],[2,"(B) Finality.—The decisions of the Administrator in making awards under this section are final."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/51/30902?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§30902. Charles \"Pete\" Conrad Astronomy Awards","tname":"National and Commercial Space Programs","by":{"3":"10"}},{"t":"rule","label":"Fed. R. App. P. 28","url":"https://www.law.cornell.edu/rules/frap/rule_28","by":{"3":"18"}}]};